import csv,json,struct,hashlib,random
from pathlib import Path
from unicorn import *
from unicorn.x86_const import *
R=Path(__file__).resolve().parents[1];b=(R/'prior/inputs/nite3w - 110.exe').read_bytes();assert hashlib.sha256(b).hexdigest()=='12fe5168783446275802e0e947898261b5eca6b88288f3a895fc1faa4c544481'
code=bytearray(b[0x15fc0:0x15fc0+0xefbc]);rows=[r for r in csv.DictReader((R/'pass46-results/listing.tsv').open(),delimiter='\t') if r['function']=='1010:31aa'];normalized=[]
for r in rows:
 a=int(r['address'].split(':')[1],16);v=bytes.fromhex(r['bytes'])
 if r['instruction'].startswith('CALLF'):
  normalized.append(r['address']);code[a:a+len(v)]=v
 else:assert bytes(code[a:a+len(v)])==v
(R/'pass47/controller_listing.tsv').write_text('address\tbytes\tinstruction\tfunction\n'+''.join('\t'.join(r[k] for k in ['address','bytes','instruction','function'])+'\n' for r in rows))
u=Uc(UC_ARCH_X86,UC_MODE_16);u.mem_map(0,0x100000);u.mem_write(0x20000,bytes(code));D=0x10480;events=[];rng=random.Random(47)
def hook(u,a,n,data):
 off=a-0x20000
 if off not in [0x31b4,0x333e,0x334a,0x3356]:return
 sp=u.reg_read(UC_X86_REG_SP);w=lambda k:struct.unpack('<H',u.mem_read(D+sp+k,2))[0]
 if off==0x31b4:assert w(0)==0x1357;pop=2;ret=0x2468;events.append('GETDC')
 elif off==0x333e:
  ptr,seg,count,start,handle=[w(i) for i in range(0,10,2)];assert (seg,count,start,handle)==(0x1048,236,10,H)
  assert bytes(u.mem_read((seg<<4)+ptr,944))==expected;pop=10;ret=RET;events.append('ANIMATEPALETTE')
 elif off==0x334a:pop=0;ret=RET;events.append('3100')
 else:assert [w(0),w(2)]==[0x2468,0x1357];pop=4;ret=RET;events.append('RELEASEDC')
 u.reg_write(UC_X86_REG_SP,sp+pop);u.reg_write(UC_X86_REG_AX,ret);u.reg_write(UC_X86_REG_IP,off+5)
u.hook_add(UC_HOOK_CODE,hook);cases=0
for mode in [2,1,3,0xffff]:
 for H in [0,1,0xffff]:
  for reserve in [0,1,255]:
   for flag in [0,1,128,255]:
    for RET in [0,0xffff]:
     palette=rng.randbytes(768);cache=rng.randbytes(16);expected=b''.join(palette[i*3:i*3+3]+b'\1' for i in range(10,246));events.clear()
     for reg,v in [(UC_X86_REG_CS,0x2000),(UC_X86_REG_DS,0x1048),(UC_X86_REG_SS,0x1048),(UC_X86_REG_SP,0xd000),(UC_X86_REG_BP,0xe000),(UC_X86_REG_SI,0x9876),(UC_X86_REG_DI,0x5432),(UC_X86_REG_EFLAGS,2)]:u.reg_write(reg,v)
     for off,v in [(0x7000,palette),(0x327e,cache),(0xc4,bytes([flag])),(0xbe,struct.pack('<H',H)),(0xb6,struct.pack('<H',0x1357)),(0x46af,bytes([reserve])),(0xd000,struct.pack('<5H',0xf000,0x2000,0x7000,mode,0xbeef))]:u.mem_write(D+off,v)
     u.emu_start(0x231aa,0x2f000,count=20000)
     want=['GETDC']+(['ANIMATEPALETTE'] if mode==2 and H else [])+(['3100'] if mode==2 and reserve==0 else [])+['RELEASEDC'];assert events==want
     assert bytes(u.mem_read(D+0xc4,1))==bytes([flag]) and bytes(u.mem_read(D+0x327e,16))==cache
     assert bytes(u.mem_read(D+0x7000,768))==palette
     for reg,v in [(UC_X86_REG_SP,0xd004),(UC_X86_REG_BP,0xe000),(UC_X86_REG_SI,0x9876),(UC_X86_REG_DI,0x5432),(UC_X86_REG_DS,0x1048)]:assert u.reg_read(reg)==v
     cases+=1
out=dict(controller_cases=cases,mode2_cases=72,other_modes=[1,3,65535],normalized_call_encodings=normalized,stubs=['GETDC returns2468,pop2','ANIMATEPALETTE returns0/FFFF,pop10','3100 returns0/FFFF,no effects','RELEASEDC returns0/FFFF,pop4'],full_game_runtime=False,limits=['Mode0 excluded','Calls intercepted before CALLF; Windows and3100 side effects absent','Cache preservation conditional on no-effect stubs','Synthetic fixtures, not actual Win16 imports'])
assert cases==288
(R/'pass47/controller_verification.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out))

